def resolve(path, cwd, links):
    if path is None or cwd is None or links is None:
        return None

    # Start with the absolute path
    if path.startswith('/'):
        current = path
    else:
        current = cwd + '/' + path if cwd != '/' else '/' + path

    # Split into components and process
    components = current.split('/')
    result = []
    link_count = 0
    i = 0

    while i < len(components):
        comp = components[i]

        # Empty components and '.' are skipped
        if comp == '' or comp == '.':
            i += 1
            continue

        # '..' moves to parent
        if comp == '..':
            if result:
                result.pop()
            i += 1
            continue

        # Append the component
        result.append(comp)

        # Build the current canonical path
        if result:
            current_path = '/' + '/'.join(result)
        else:
            current_path = '/'

        # Check if this path is a symlink
        if current_path in links:
            link_count += 1
            if link_count > 8:
                return None

            target = links[current_path]

            # Resolve the target relative to the directory containing the link
            if target.startswith('/'):
                # Absolute target
                target_components = target.split('/')
            else:
                # Relative target - relative to the directory containing the link
                if len(result) > 1:
                    link_dir = result[:-1]
                else:
                    link_dir = []
                target_components = (link_dir + target.split('/'))

            # Remove the last appended component (the symlink itself)
            result.pop()

            # Process remaining original components + target components
            remaining = components[i+1:]
            components = target_components + remaining
            i = 0
            continue

        i += 1

    # Build final result
    if result:
        return '/' + '/'.join(result)
    else:
        return '/'

